export interface ConnectorConfig {
  /** Slack bot token with chat:write scope. */
  slackBotToken: string
  /** Slack channel ID or name (e.g., C1234567890 or #general). */
  slackChannel: string
  /** Injected fetch for testing. */
  fetch?: typeof fetch
}

export interface CalendlyWebhookPayload {
  resource: {
    type: string
    uri: string
  }
  invitee: {
    name: string
    email: string
    uri: string
  }
  answers: Record<string, string>
}

export interface HandleResult {
  ok: boolean
  channel: string
  ts: string
  message: {
    text: string
    type: string
    subtype: string
    ts: string
  }
}

function formatAnswers(answers: Record<string, string>): string {
  return Object.entries(answers)
    .map(([question, answer]) => `${question} -> ${answer}`)
    .join(', ')
}

function buildMessageText(payload: CalendlyWebhookPayload): string {
  const answersText = formatAnswers(payload.answers)
  return `New meeting booked!\nName: ${payload.invitee.name}\nEmail: ${payload.invitee.email}\nAnswers: ${answersText}`
}

export async function handle(
  payload: CalendlyWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  if (!payload.invitee?.name) {
    throw new Error('Missing required field: invitee.name')
  }
  if (!payload.invitee?.email) {
    throw new Error('Missing required field: invitee.email')
  }
  if (!payload.answers) {
    throw new Error('Missing required field: answers')
  }

  const text = buildMessageText(payload)

  const fetchImpl = config.fetch ?? fetch
  const response = await fetchImpl('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      channel: config.slackChannel,
      text,
    }),
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at POST https://slack.com/api/chat.postMessage`)
  }

  const data = await response.json() as HandleResult
  return data
}

